-- Ejecutar este script conectado a la base de datos sabornetdb.
-- En DBeaver, crear la base desde la conexión de PostgreSQL si todavía no existe,
-- luego conectarse a sabornetdb y ejecutar este archivo como script.

CREATE TABLE IF NOT EXISTS "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(20) NOT NULL,
    "Email"  VARCHAR(30)  NOT NULL,
    "Password" VARCHAR NOT NULL,
    "AvatarUrl" VARCHAR NOT NULL,
    "rol" integer NOT NULL
);

CREATE TABLE IF NOT EXISTS "Categorias" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(30) NOT NULL
);

CREATE TABLE IF NOT EXISTS "Ingredientes" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" VARCHAR NOT NULL,
    "unidadDeMedida" VARCHAR NOT NULL
);

CREATE TABLE IF NOT EXISTS "Recetas" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Titulo" VARCHAR(70) NOT NULL,
    "Descripcion" VARCHAR NOT NULL,
    "Instrucciones" text NOT NULL,
    "TiempoMinutos" integer NOT NULL,
    "FotoPrincipal" VARCHAR NOT NULL,
    "FechaDeLaReceta" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UsuarioID" integer NOT NULL REFERENCES "Usuarios" ("Id"),
    "CategoriaID" integer NOT NULL REFERENCES "Categorias" ("ID")
);

ALTER TABLE "Recetas"
    ADD COLUMN IF NOT EXISTS "FechaDeLaReceta"
    timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;

CREATE TABLE IF NOT EXISTS "RecetaIngredientes" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RecetaId" integer NOT NULL REFERENCES "Recetas" ("ID"),
    "IngredienteId" integer NOT NULL REFERENCES "Ingredientes" ("ID"),
    "Cantidad" numeric NOT NULL
);

CREATE TABLE IF NOT EXISTS "comentarios" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "comentario" VARCHAR NOT NULL,
    "califiacion" integer NOT NULL,
    "fechaCreacion" timestamp with time zone NOT NULL,
    "UsuarioID" integer NOT NULL REFERENCES "Usuarios" ("Id"),
    "RecetaID" integer NOT NULL REFERENCES "Recetas" ("ID")
);
